// Account visual baselines (#289): every viewport × theme project (360/768/1280, light and dark)
// with the clock frozen: `/account` (profile and security) and the two-factor setup dialog open.
// Per-run values are masked: the session table (IPs, sign-in times) and the QR code and key (a new
// secret each time). Baselines live in e2e/__screenshots__ and are only ever generated by the e2e
// workflow's `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md);
// without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { expect, test } from '../../fixtures/index.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

async function open(page: Page, asUser: AsUser) {
  await asUser('owner');
  await page.goto('/account');
  await expect(page.getByRole('heading', { level: 1, name: 'Account' })).toBeVisible();
  await expect(page.getByRole('table', { name: 'Your active sessions' })).toBeVisible();
}

const masks = (page: Page) => [
  page.locator('[data-slot="session-table"]'),
  page.locator('[data-slot="two-factor-qr"]'),
  page.locator('[data-slot="two-factor-secret"]'),
];

interface Shot {
  name: string;
  setUp: (page: Page, asUser: AsUser) => Promise<void>;
}

const SHOTS: readonly Shot[] = [
  { name: 'account.png', setUp: open },
  {
    name: 'account-two-factor-dialog.png',
    setUp: async (page, asUser) => {
      await open(page, asUser);
      await page.getByRole('button', { name: 'Set up' }).click();
      await expect(
        page.getByRole('img', { name: 'QR code for your authenticator app' }),
      ).toBeVisible();
    },
  },
];

test.describe('account visual baselines', () => {
  for (const shot of SHOTS) {
    test(shot.name, async ({ page, asUser }, testInfo) => {
      skipWithoutBaseline(testInfo, shot.name);
      await shot.setUp(page, asUser);
      await expect(page).toHaveScreenshot(shot.name, {
        animations: 'disabled',
        caret: 'hide',
        fullPage: true,
        mask: masks(page),
      });
    });
  }
});
